class Base {
public:
    // VTABLE ENTRY 0
    virtual void run() const = 0; 
    // VTABLE ENTRY 1 (Destructor)
    virtual ~Base() = default;
};

class Derived : public Base {
public:
    // Overrides VTABLE ENTRY 0
    void run() const override {}
};

Derived d;
// b_ptr holds d's vptr pointing to Derived::vtable
Base* b_ptr = &d; 

// Runtime Dispatch: 
// Reads vptr -> accesses vtable -> calls function pointer
b_ptr->run();
